def transform(grid):
    g = np.array(grid)
    out = g.copy()
    H, W = g.shape
    comps = components(g == 0, diagonal=False)
    for c in comps:
        touch = False
        for y, x in c:
            for dy, dx in ((0, 1), (0, -1), (1, 0), (-1, 0)):
                yy, xx = y + dy, x + dx
                if 0 <= yy < H and 0 <= xx < W and g[yy, xx] == 1:
                    touch = True
                    break
            if touch:
                break
        if touch:
            for y, x in c:
                out[y, x] = 1
            emit(out, f"Flood the {len(c)}-cell empty region touching an existing 1 with colour 1.")
    emit(out, "All empty regions orthogonally touching a 1 are filled; isolated pockets stay 0.")
    return out
